const ANCHOR = new Date("2026-04-10T12:00:00Z");

/** Signed hours from ANCHOR to the given ISO string. Negative = past. */
export function hoursFromNow(iso: string): number {
  const dueMs = new Date(iso).getTime();
  const nowMs = ANCHOR.getTime();
  return Math.round((dueMs - nowMs) / (1000 * 60 * 60));
}

export function formatSlaChip(slaDueAt: string): {
  label: string;
  tone: "ok" | "warning" | "breached";
} {
  const hours = hoursFromNow(slaDueAt);

  if (hours < 0) {
    const abs = Math.abs(hours);
    const label =
      abs >= 24 ? `${Math.floor(abs / 24)}d overdue` : `${abs}h overdue`;
    return { label, tone: "breached" };
  }

  if (hours < 24) {
    return { label: `in ${hours}h`, tone: "warning" };
  }

  const days = Math.floor(hours / 24);
  return { label: `in ${days}d`, tone: "ok" };
}

export function formatRelative(iso: string): string {
  const diffMs = ANCHOR.getTime() - new Date(iso).getTime();
  const diffHours = Math.floor(diffMs / (1000 * 60 * 60));

  if (diffHours < 1) return "just now";
  if (diffHours < 24) return `${diffHours}h ago`;

  const diffDays = Math.floor(diffHours / 24);
  if (diffDays < 7) return `${diffDays}d ago`;

  const diffWeeks = Math.floor(diffDays / 7);
  return `${diffWeeks}w ago`;
}

import type { RequestStatus } from "@/lib/types";

interface StatusBadgeProps {
  status: RequestStatus;
}

const STATUS_MAP: Record<
  RequestStatus,
  { label: string; className: string }
> = {
  backlog: {
    label: "Backlog",
    className: "bg-sky-100 text-sky-700 ring-1 ring-sky-200",
  },
  in_progress: {
    label: "In Progress",
    className: "bg-slate-100 text-slate-700 ring-1 ring-slate-200",
  },
  review: {
    label: "Review",
    className: "bg-amber-100 text-amber-800 ring-1 ring-amber-200",
  },
  delivered: {
    label: "Delivered",
    className: "bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200",
  },
};

export function StatusBadge({ status }: StatusBadgeProps) {
  const config = STATUS_MAP[status];
  return (
    <span
      className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${config.className}`}
    >
      {config.label}
    </span>
  );
}

