    <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap bg-red-100 text-red-700 ring-1 ring-red-200">
      <Flame className="size-3" />
      Urgent
    </span>
