interface InboxTableProps {
  requests: readonly Request[];
  clients: readonly Client[];
  assignees: readonly Assignee[];
  onClearFilters?: () => void;
}

function getInitials(name: string): string {
  return name
    .split(" ")
    .map((n) => n[0] ?? "")
    .slice(0, 2)
    .join("")
    .toUpperCase();
}

function SlaChip({ slaDueAt }: { slaDueAt: string }) {
  const { label, tone } = formatSlaChip(slaDueAt);
  const colorClass =
    tone === "breached"
      ? "bg-red-100 text-red-700 ring-1 ring-red-200"
      : tone === "warning"
        ? "bg-amber-100 text-amber-700 ring-1 ring-amber-200"
        : "bg-muted text-muted-foreground ring-1 ring-border";
  return (
    <span
      className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${colorClass}`}
    >
      {label}
    </span>
  );
}

export function InboxTable({
  requests,
  clients,
  assignees,
  onClearFilters,
}: InboxTableProps) {
  const clientMap = new Map(clients.map((c) => [c.id, c]));
  const assigneeMap = new Map(assignees.map((a) => [a.id, a]));

  return (
    <Card className="overflow-hidden">
      <CardContent className="p-0">
        {requests.length === 0 ? (
          <EmptyState
            icon={Inbox}
            title="No matching requests"
            description="Try clearing your filters to see all requests."
            action={{ label: "Clear filters", onClick: onClearFilters }}
          />
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="pl-4 min-w-[200px]">Title</TableHead>
                  <TableHead className="min-w-[140px]">Client</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="hidden md:table-cell">Priority</TableHead>
                  <TableHead className="hidden md:table-cell">Assignee</TableHead>
                  <TableHead>SLA</TableHead>
                  <TableHead>Created</TableHead>
                  <TableHead className="w-20 text-right pr-4">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {requests.map((req) => {
                  const client = clientMap.get(req.clientId);
                  const assignee = assigneeMap.get(req.assigneeId);

                  return (
                    <TableRow
                      key={req.id}
                      className="cursor-pointer hover:bg-muted/30"
                      onClick={() => {
                        /* TODO(phase2): navigate to request detail */
                      }}
                    >
                      {/* Title */}
                      <TableCell className="pl-4 font-medium max-w-[240px]">
                        <span className="truncate block">{req.title}</span>
                      </TableCell>

                      {/* Client */}
                      <TableCell>
                        {client ? (
                          <div className="flex items-center gap-2">
                            <Avatar size="sm">
                              <AvatarImage
                                src={client.avatarUrl}
                                alt={client.name}
                              />
                              <AvatarFallback>
                                {getInitials(client.name)}
                              </AvatarFallback>
                            </Avatar>
                            <span className="text-sm truncate max-w-[100px]">
                              {client.company}
                            </span>
                          </div>
                        ) : (
                          <span className="text-muted-foreground text-xs">—</span>
                        )}
                      </TableCell>

                      {/* Status */}
                      <TableCell>
                        <StatusBadge status={req.status} />
                      </TableCell>

                      {/* Priority — hidden on md and below */}
                      <TableCell className="hidden md:table-cell">
                        <PriorityBadge priority={req.priority} />
                      </TableCell>

                      {/* Assignee — hidden on md and below */}
                      <TableCell className="hidden md:table-cell">
                        {assignee ? (
                          <div className="flex items-center gap-2">
                            <Avatar size="sm">
                              <AvatarImage
                                src={assignee.avatarUrl}
                                alt={assignee.name}
                              />
                              <AvatarFallback>
                                {getInitials(assignee.name)}
                              </AvatarFallback>
                            </Avatar>
                            <span className="text-xs text-muted-foreground truncate max-w-[80px]">
                              {assignee.name.split(" ")[0]}
                            </span>
                          </div>
                        ) : (
                          <span className="text-muted-foreground text-xs">—</span>
                        )}
                      </TableCell>

                      {/* SLA */}
                      <TableCell>
                        <SlaChip slaDueAt={req.slaDueAt} />
                      </TableCell>

                      {/* Created */}
                      <TableCell className="text-muted-foreground text-xs">
                        {formatRelative(req.createdAt)}
                      </TableCell>

                      {/* Actions */}
                      <TableCell
                        className="text-right pr-4"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="size-7 p-0"
                            aria-label="Edit request"
                            onClick={(e) => {
                              e.stopPropagation();
                              /* TODO(phase2): open edit dialog */
                            }}
                          >
                            <Pencil className="size-3.5" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            className="size-7 p-0"
                            aria-label="Archive request"
                            onClick={(e) => {
                              e.stopPropagation();
                              /* TODO(phase2): archive request */
                            }}
                          >
                            <Archive className="size-3.5" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>

            {/* Footer */}
            <div className="px-4 py-3 border-t text-xs text-muted-foreground">
              Showing {requests.length} of {requests.length}
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

