"use client";

import { useMemo, useState } from "react";
import { requests as allRequests, clients, assignees } from "@/lib/mock";
import { PageHeader } from "@/components/common/page-header";
import { ViewToggle, type ViewMode } from "@/components/inbox/view-toggle";
import { FilterBar, type InboxFilters } from "@/components/inbox/filter-bar";
import { InboxTable } from "@/components/inbox/inbox-table";
import { InboxKanban } from "@/components/inbox/inbox-kanban";

const DEFAULT_FILTERS: InboxFilters = {
  search: "",
  status: "all",
  priority: "all",
  clientId: "all",
};

export default function InboxPage() {
  const [view, setView] = useState<ViewMode>("table");
  const [filters, setFilters] = useState<InboxFilters>(DEFAULT_FILTERS);

  const filtered = useMemo(() => {
    return allRequests.filter((r) => {
      if (filters.status !== "all" && r.status !== filters.status) return false;
      if (filters.priority !== "all" && r.priority !== filters.priority)
        return false;
      if (filters.clientId !== "all" && r.clientId !== filters.clientId)
        return false;
      if (filters.search) {
        const q = filters.search.toLowerCase();
        if (
          !r.title.toLowerCase().includes(q) &&
          !r.rawMessage.toLowerCase().includes(q)
        )
          return false;
      }
      return true;
    });
  }, [filters]);

  const hasActiveFilters =
    filters.search !== "" ||
    filters.status !== "all" ||
    filters.priority !== "all" ||
    filters.clientId !== "all";

  function handleClear() {
    setFilters(DEFAULT_FILTERS);
  }

  return (
    <>
      <PageHeader
        title="Inbox"
        subtitle="All client requests in one place"
        actions={<ViewToggle value={view} onChange={setView} />}
      />
      <div className="space-y-4">
        <FilterBar
          filters={filters}
          onChange={setFilters}
          onClear={handleClear}
          hasActiveFilters={hasActiveFilters}
          clients={clients}
        />
        {view === "table" ? (
          <InboxTable
            requests={filtered}
            clients={clients}
            assignees={assignees}
            onClearFilters={handleClear}
          />
        ) : (
          <InboxKanban
            requests={filtered}
            clients={clients}
            assignees={assignees}
          />
        )}
      </div>
    </>
  );
}

